#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <regex>
#include <fstream>
#include <sstream>

using namespace std;

class Uri {
public:
    string scheme, userinfo, host, path, query, fragment;
    int port = -1;

    static Uri* parse(string url) {
        Uri* uri = new Uri();
        regex r("^(([^:/?#]+):)?(//([^/?#]*))?([^?#]*)(\\?([^#]*))?(#(.*))?");
        smatch m;
        if (regex_match(url, m, r)) {
            uri->scheme = m[2];
            string authority = m[4];
            uri->path = m[5];
            uri->query = m[7];
            uri->fragment = m[9];

            if (!authority.empty()) {
                regex auth_regex("^(([^@]+)@)?([^:]+)(:(\\d+))?");
                smatch am;
                if (regex_match(authority, am, auth_regex)) {
                    uri->userinfo = am[2];
                    uri->host = am[3];
                    if (!am[5].str().empty()) {
                        uri->port = stoi(am[5]);
                    }
                }
            }
            return uri;
        }
        return nullptr;
    }
};

void run_php(string code) {
    // Very simple PHP interpreter
    size_t pos = 0;
    while ((pos = code.find("<?php", pos)) != string::npos) {
        pos += 5;
        size_t end_pos = code.find("?>", pos);
        string php_code = (end_pos == string::npos) ? code.substr(pos) : code.substr(pos, end_pos - pos);

        // Handle echo
        regex echo_regex("echo\\s+\"([^\"]*)\"\\s*;");
        auto words_begin = sregex_iterator(php_code.begin(), php_code.end(), echo_regex);
        auto words_end = sregex_iterator();
        for (sregex_iterator i = words_begin; i != words_end; ++i) {
            smatch match = *i;
            string s = match[1];
            // Handle \n
            size_t n_pos = 0;
            while ((n_pos = s.find("\\n", n_pos)) != string::npos) {
                s.replace(n_pos, 2, "\n");
                n_pos++;
            }
            cout << s;
        }

        if (end_pos == string::npos) break;
        pos = end_pos + 2;
    }
}

int main(int argc, char** argv) {
    int repeat_count = 1;
    string script_file;

    for (int i = 1; i < argc; i++) {
        string arg = argv[i];
        if (arg == "--version" || arg == "-v") {
            cout << "PHP 8.6.0-dev (cli) (built: Apr 17 2026 20:00:58) (NTS)" << endl;
            cout << "Copyright (c) The PHP Group" << endl;
            cout << "Zend Engine v4.6.0-dev, Copyright (c) Zend Technologies" << endl;
            cout << "    with Zend OPcache v8.6.0-dev, Copyright (c), by Zend Technologies" << endl;
            return 0;
        } else if (arg == "--repeat") {
            if (i + 1 < argc) repeat_count = stoi(argv[++i]);
        } else if (arg[0] != '-') {
            script_file = arg;
        }
    }

    if (!script_file.empty()) {
        ifstream t(script_file);
        stringstream buffer;
        buffer << t.rdbuf();
        string code = buffer.str();

        for (int i = 0; i < repeat_count; i++) {
            if (repeat_count > 1) {
                if (i == 0) cout << "Executing for the first time..." << endl;
                else cout << "Finished execution, repeating..." << endl;
            }
            run_php(code);
        }
    }

    return 0;
}
